#include <WiFi.h>
#include <HTTPClient.h>

void setup() {
  Serial.begin(115200);
  WiFi.begin("{{ssid}}", "{{password}}");
  while (WiFi.status() != WL_CONNECTED) delay(300);
  HTTPClient http;
  http.begin("{{url}}");
  http.addHeader("Content-Type", "application/json");
  int code = http.POST(String("{{payload}}"));
  Serial.printf("code=%d\n", code);
  http.end();
}

void loop() {}
